1	/**
2	 * Intervalo de tempo entre dois instantes. Objeto de valor: não tem identidade
3	 * e é imutável.
4	 *
5	 * Guarda os instantes como número (epoch) e devolve `Date` novo a cada acesso.
6	 * Um `readonly inicio: Date` não seria imutável de verdade — `Date` é mutável,
7	 * e quem recebesse o objeto poderia chamar `setHours` nele e alterar o período
8	 * por baixo de todo mundo.
9	 */
10	export class Periodo {
11	  private constructor(
12	    private readonly inicioEm: number,
13	    private readonly fimEm: number,
14	  ) {}
15	
16	  static de(inicio: Date, fim: Date): Periodo {
17	    if (Number.isNaN(inicio.getTime()) || Number.isNaN(fim.getTime())) {
18	      throw new Error("Um período exige datas válidas.");
19	    }
20	    if (fim.getTime() <= inicio.getTime()) {
21	      throw new Error("O fim de um período deve ser posterior ao início.");
22	    }
23	    return new Periodo(inicio.getTime(), fim.getTime());
24	  }
25	
26	  get inicio(): Date {
27	    return new Date(this.inicioEm);
28	  }
29	
30	  get fim(): Date {
31	    return new Date(this.fimEm);
32	  }
33	
34	  /**
35	   * Intervalo semiaberto: inclui o início, exclui o fim.
36	   *
37	   * É essa escolha que impede o painel de piscar "livre" por uma fração de
38	   * segundo quando uma reunião termina exatamente quando a seguinte começa —
39	   * às 12:00 em ponto, a reunião de 11:00–12:00 já não contém o instante, e a
40	   * de 12:00–13:00 já contém.
41	   */
42	  contem(instante: Date): boolean {
43	    const agora = instante.getTime();
44	    return agora >= this.inicioEm && agora < this.fimEm;
45	  }
46	
47	  comecaDepoisDe(instante: Date): boolean {
48	    return this.inicioEm > instante.getTime();
49	  }
50	
51	  terminouAte(instante: Date): boolean {
52	    return this.fimEm <= instante.getTime();
53	  }
54	
55	  /** Verdadeiro quando este período começa antes (ou junto) do fim do outro. */
56	  encostaEm(outro: Periodo): boolean {
57	    return this.inicioEm <= outro.fimEm && this.fimEm > outro.fimEm;
58	  }
59	
60	  comecaAntesDe(outro: Periodo): boolean {
61	    return this.inicioEm < outro.inicioEm;
62	  }
63	
64	  duracaoEmMinutos(): number {
65	    return Math.round((this.fimEm - this.inicioEm) / 60_000);
66	  }
67	
68	  minutosAte(instante: Date): number {
69	    return Math.round((this.fimEm - instante.getTime()) / 60_000);
70	  }
71	}
