3	/**
4	 * Como o compromisso deixa a sala. Vocabulário do negócio, não do Outlook: a
5	 * tradução dos valores do Graph (`busy`, `oof`, `tentative`...) acontece no
6	 * adaptador, na camada de infraestrutura.
7	 */
8	export type Disponibilidade = "LIVRE" | "PROVISORIA" | "OCUPADA" | "AUSENTE";
9	
10	/**
11	 * Compromisso marcado na agenda de uma sala. Entidade interna do agregado
12	 * AgendaDaSala — nunca é buscada ou persistida por fora dele.
13	 */
14	export class Reserva {
15	  constructor(
16	    public readonly id: string,
17	    public readonly titulo: string,
18	    public readonly periodo: Periodo,
19	    private readonly disponibilidade: Disponibilidade,
20	    private readonly cancelada: boolean,
21	    public readonly diaInteiro: boolean,
22	    public readonly privada: boolean,
23	  ) {}
24	
25	  /**
26	   * Nem todo compromisso na agenda tira a sala de circulação.
27	   *
28	   * Um convite ainda não aceito (PROVISORIA) ou marcado como livre não impede
29	   * ninguém de usar a sala — tratá-los como ocupação faria o painel mostrar
30	   * vermelho numa sala vazia, que é o erro que mais rápido faz as pessoas
31	   * pararem de confiar no tablet.
32	   */
33	  ocupaASala(): boolean {
34	    if (this.cancelada) {
35	      return false;
36	    }
37	    return this.disponibilidade === "OCUPADA" || this.disponibilidade === "AUSENTE";
38	  }
39	
40	  /**
41	   * O que pode ser exibido num tablet de corredor. Reunião privada nunca
42	   * mostra o título, mesmo com MOSTRAR_TITULO ligado.
43	   */
44	  tituloVisivel(mostrarTitulo: boolean): string {
45	    if (this.privada) {
46	      return "Reunião privada";
47	    }
48	    if (!mostrarTitulo) {
49	      return "Reservada";
50	    }
51	    return this.titulo.trim() === "" ? "Reservada" : this.titulo;
52	  }
53	}
